comments.body:
Also, for the context, I wonder if we can pipe it through `self` and then instead remove the `JSONRPCRequest` instead of `RPCMethod`:

```diff
diff --git a/src/rpc/server.cpp b/src/rpc/server.cpp
index 3852358..6123c38 100644
--- a/src/rpc/server.cpp
+++ b/src/rpc/server.cpp
@@ -170,3 +170,3 @@ static RPCMethod stop()
                 RPCExamples{""},
-        [](const RPCMethod& self, const JSONRPCRequest& jsonRequest) -> UniValue
+        [](const RPCMethod& self, const JSONRPCRequest&) -> UniValue
 {
@@ -174,5 +174,5 @@ static RPCMethod stop()
     // this reply will get back to the client.
-    CHECK_NONFATAL((CHECK_NONFATAL(EnsureAnyNodeContext(jsonRequest.context).shutdown_request))());
-    if (jsonRequest.params[0].isNum()) {
-        UninterruptibleSleep(std::chrono::milliseconds{jsonRequest.params[0].getInt<int>()});
+    CHECK_NONFATAL((CHECK_NONFATAL(EnsureAnyNodeContext(self.Context()).shutdown_request))());
+    if (const auto wait{self.MaybeArg<int>("wait")}) {
+        UninterruptibleSleep(std::chrono::milliseconds{*wait});
     }
